import React, { useState, useEffect } from 'react';
import { MessageCircle } from 'lucide-react';

import Loader from './components/Loader';
import TypographySample from './pages/TypographySample';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import WhatsAppCta from './components/WhatsAppCta';
import About from './components/About';
import Packages from './components/Packages';
import Commission from './components/Commission';
import HowItWorks from './components/HowItWorks';
import Requirements from './components/Requirements';
import Terms from './components/Terms';
import Testimonials from './components/Testimonials';
import Contact from './components/Contact';
import Footer from './components/Footer';

export default function App() {
  const [loading, setLoading] = useState(true);
  const [typographyDemo, setTypographyDemo] = useState(
    () =>
      typeof window !== 'undefined' &&
      new URLSearchParams(window.location.search).get('demo') === 'typography'
  );

  useEffect(() => {
    const t = setTimeout(() => setLoading(false), 1500);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    const onPop = () =>
      setTypographyDemo(new URLSearchParams(window.location.search).get('demo') === 'typography');
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  if (typographyDemo) {
    return <TypographySample />;
  }

  return (
    <>
      {loading && <Loader />}

      <div
        style={{
          opacity: loading ? 0 : 1,
          transition: 'opacity 0.5s ease 0.2s',
        }}
      >
        <Navbar />
        <Hero />
        <WhatsAppCta />
        <About />
        <Packages />
        <Commission />
        <HowItWorks />
        <Requirements />
        <Terms />
        <Testimonials />
        <Contact />
        <Footer />

        {/* ✅ Floating WhatsApp Button (Improved) */}
        <a
          href="https://wa.me/9233085"
          target="_blank"
          rel="noopener noreferrer"
          className="fixed bottom-6 right-6 z-[60] group"
        >
          {/* Ping Effect */}
          <span className="absolute inset-0 rounded-full bg-[#25D366] animate-ping opacity-70"></span>

          {/* Button */}
          <div className="relative bg-[#25D366] text-white p-4 rounded-full shadow-xl flex items-center justify-center transition-all duration-300 hover:scale-110 active:scale-95">

            {/* ✅ Lucide Icon */}
            <MessageCircle className="w-7 h-7" />

          </div>

          {/* Tooltip */}
          <span className="absolute right-20 top-1/2 -translate-y-1/2 bg-black text-white text-xs px-3 py-1 rounded opacity-0 group-hover:opacity-100 transition whitespace-nowrap">
            Chat on WhatsApp
          </span>
        </a>
      </div>
    </>
  );
}
